#!/bin/bash
set -e
DIR=/opt/hermes-chat-agent
mkdir -p $DIR/chat_agent
cd $DIR
cp -f $DIR/chat_agent/state.json $DIR/chat_agent/state.v2.json 2>/dev/null || true
base64 -d > /opt/hermes-chat-agent/chat_agent.py <<'B64EOF'

B64EOF

# fresh v3 state (seed to avoid mass-messaging)
echo '{"chats": {}}' > $DIR/chat_agent/state.json

cat > /etc/systemd/system/hermes-chat-agent.service <<'UNITEOF'
[Unit]
Description=Avito chat auto-responder v3
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
WorkingDirectory=/opt/hermes-chat-agent
EnvironmentFile=/etc/default/hermes-chat-agent
Environment=PYTHONUNBUFFERED=1
ExecStartPre=/usr/bin/python3 /opt/hermes-chat-agent/chat_agent.py seed
ExecStart=/usr/bin/python3 /opt/hermes-chat-agent/chat_agent.py poll
Restart=always
RestartSec=20
StandardOutput=append:/var/log/hermes-chat-agent.log
StandardError=append:/var/log/hermes-chat-agent.log

[Install]
WantedBy=multi-user.target
UNITEOF

systemctl daemon-reload
systemctl restart hermes-chat-agent
sleep 12
echo "=== STATUS ==="
systemctl is-active hermes-chat-agent
echo "=== PROC ==="
pgrep -af "chat_agent.py" | head -3
echo "=== LOG ==="
tail -n 8 /var/log/hermes-chat-agent.log
echo "=== END ==="
